import heapq

def match(orders):
    trades = []
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    info = {}       # id -> dict with side, price, qty, seq, active
    seq = 0

    for o in orders:
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            if oid in info and info[oid]['active']:
                info[oid]['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = o
        elif typ == 'ioc':
            _, oid, side, price, qty = o
        elif typ == 'market':
            _, oid, side, qty = o
            price = None
        else:
            continue

        seq += 1
        rem = qty

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while rem > 0 and opp_heap:
            top = opp_heap[0]
            opp_id = top[2]

            if opp_id not in info or not info[opp_id]['active']:
                heapq.heappop(opp_heap)
                continue

            opp_price = info[opp_id]['price']

            if typ == 'market' or price is None:
                cond = True
            else:
                if side == 'buy':
                    cond = opp_price <= price
                else:
                    cond = opp_price >= price

            if not cond:
                break

            opp_qty = info[opp_id]['qty']
            trade_qty = min(rem, opp_qty)

            if side == 'buy':
                trades.append([oid, opp_id, opp_price, trade_qty])
            else:
                trades.append([opp_id, oid, opp_price, trade_qty])

            rem -= trade_qty
            info[opp_id]['qty'] -= trade_qty

            if info[opp_id]['qty'] == 0:
                info[opp_id]['active'] = False
                heapq.heappop(opp_heap)

        if typ == 'limit':
            if rem > 0:
                info[oid] = {'side': side, 'price': price, 'qty': rem, 'seq': seq, 'active': True}
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, seq, oid))
                else:
                    heapq.heappush(sell_heap, (price, seq, oid))
            else:
                info[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': seq, 'active': False}
        else:
            # ioc or market: discard remainder
            info[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': seq, 'active': False}

    return trades

